var l=[{title:`Дорослі віком 18–64`,text:`Настанови Всесвітньої організації охорони здоров’я рекомендують 150–300 хвилин аеробної активності помірної інтенсивності на тиждень, або 75–150 хвилин активності високої інтенсивності, або еквівалентну суміш обох. Вони також рекомендують м’язозміцнювальну активність для всіх основних груп м’язів щонайменше у два дні на тиждень. Більша активність може дати додаткові переваги, але потрібна кількість залежить від вашого здоров’я та можливостей.`},{title:`Що означає інтенсивність`,text:`Помірна активність підвищує дихання й пульс, але ви все ще можете підтримувати розмову. Висока інтенсивність ускладнює мовлення повними реченнями. Швидка ходьба чи легка їзда на велосипеді вважаються помірними, а біг чи швидка їзда вважаються високоінтенсивними. Хвилини можна розподілити впродовж тижня в заняттях, що вписуються у ваш розклад, тож одне довге тренування не обов’язкове.`},{title:`Літні люди та молодь`,text:`Літні люди дотримуються тих самих аеробних і силових цілей. Їм також радять багатокомпонентну активність, що наголошує на рівновазі та силі, щонайменше у три дні на тиждень, де це можливо. Для віку 5–17 років ВООЗ рекомендує в середньому щонайменше 60 хвилин активності від помірної до високої інтенсивності на день упродовж тижня, а також активність високої інтенсивності та вправи для м’язів і кісток щонайменше у три дні на тиждень.`},{title:`Початок із малого теж має значення`,text:`Будь-яке збільшення порівняно з бездіяльністю допомагає. Десятихвилинні прогулянки, підйом сходами й короткі домашні заняття: усе це наближає до рекомендованих сум. Менше сидіти корисно, навіть якщо ви вже тренуєтеся, а легка активність може замінити частину цього часу сидіння.`},{title:`Приклад`,text:`Початківець може запланувати два заняття на все тіло й три 30-хвилинні прогулянки, а потім повільно подовжувати прогулянки до аеробної цілі. Ведіть хвилини ходьби окремо від силових підходів. Настанови є цілями для цілих популяцій, тож не потрібно одразу стрибати до повної кількості.`}];var i=[{label:`Настанови ВООЗ 2020`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC9219310/`},{label:`Рекомендації CDC щодо активності`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`}];var c={sections:l,sources:i};export{c as default,l as sections,i as sources};